// Classroom question bank v2: A2 (12 topics × 24 items) for the classroom games.
// Hand-written and edited item by item to C:/lg-tools/ITEM_EDITOR_GUIDE.md: one
// defensible key, distractors a real A2 learner would choose (Turkish-speaker
// errors, neighbouring structures), a reason in the context, and diff 1/2/3 =
// 8/8/8 per topic (core, in context, contrast and nuance). Keys are balanced over
// the four positions. Student-facing text is British English; whyTr is the
// Turkish note for the teacher (≤110 characters) and rule the English label.
// youngOk: false marks items for adult groups only (work, money, long options).
// Young groups (A2: stems of 8 words or fewer) get at least 12 items per topic.
// Served to the classroom games by src/pages/sinif-oyunlari/paket/[level].json.ts.
// Ids are '<topicId>:<n>' by position: add new items at the end, never reorder.

const topic = (id, title, short, kind, items) => ({
  id,
  title,
  short,
  kind,
  items: items.map((it, i) => ({ id: `${id}:${i + 1}`, type: 'mcq', ...it })),
});

